package com.moviecatalog.movie.artwork

import jakarta.persistence.Entity
import jakarta.persistence.Id
import jakarta.persistence.Table
import java.time.Instant
import java.util.UUID

/** One artwork per movie (BR-09). The paths are relative to the artwork directory and generated by the server. */
@Entity
@Table(name = "artwork")
class Artwork(
    @Id var id: UUID,
    var movieId: UUID,
    var contentType: String,
    var sizeBytes: Long,
    var width: Int,
    var height: Int,
    var originalPath: String,
    var thumbnailPath: String,
    /** Changes on every replace; the image URLs carry it so browsers never show a stale picture. */
    var version: String,
    var createdAt: Instant,
)
